<?php
declare(strict_types=1);
require_once __DIR__.'/../../config/ui.php'; require_login('ADMIN');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id){http_response_code(400);exit('Associado inválido.');}
$get=$pdo->prepare("SELECT * FROM usuarios WHERE id=:id AND perfil='ASSOCIADO' LIMIT 1");$get->execute([':id'=>$id]);$u=$get->fetch();if(!$u){http_response_code(404);exit('Associado não encontrado.');}$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$cpf=trim($_POST['cpf']??'');$matricula=trim($_POST['matricula']??'');$status=$_POST['status_financeiro']??'';$foto=$u['foto']??null;if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$cpf===''||$matricula===''||!in_array($status,['EM_DIA','DEVEDOR','DESFILIADO'],true))throw new InvalidArgumentException('Preencha corretamente todos os campos.');if(isset($_FILES['foto'])&&$_FILES['foto']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['foto'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2097152)throw new InvalidArgumentException('A foto deve ter no máximo 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new InvalidArgumentException('Use uma imagem JPG, PNG ou WEBP.');$dir=__DIR__.'/../uploads/associados';if(!is_dir($dir))mkdir($dir,0755,true);$foto='associado_'.$id.'_'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$foto))throw new RuntimeException('Falha ao guardar foto.');if(!empty($u['foto'])&&preg_match('/^[a-zA-Z0-9_.-]+$/',$u['foto'])){@unlink($dir.'/'.$u['foto']);}}$up=$pdo->prepare('UPDATE usuarios SET nome=:nome,email=:email,cpf=:cpf,matricula=:matricula,status_financeiro=:status,foto=:foto WHERE id=:id');$up->execute([':nome'=>$nome,':email'=>$email,':cpf'=>$cpf,':matricula'=>$matricula,':status'=>$status,':foto'=>$foto,':id'=>$id]);audit('ALTERACAO_CADASTRAL','usuarios',$id,$u,['nome'=>$nome,'email'=>$email,'cpf'=>$cpf,'matricula'=>$matricula,'status_financeiro'=>$status,'foto'=>$foto]);$success='Dados atualizados com sucesso.';$get->execute([':id'=>$id]);$u=$get->fetch();}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){$error='E-mail, CPF ou matrícula já estão em uso.';}}
admin_start('Editar associado','associados.php');?><div class="mb-8"><a href="<?=e(app_url('admin/perfil.php?id='.$id))?>" class="text-sm font-semibold text-blue-600">← Voltar ao perfil</a><h2 class="mt-3 text-3xl font-extrabold">Editar associado</h2></div><?php if($success):?><div class="mb-5 rounded-lg bg-green-50 p-4 text-sm text-green-700"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 p-4 text-sm text-red-700"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="shadow-soft max-w-3xl rounded-xl border border-slate-100 bg-white p-7"><?=csrf_field()?><div class="mb-6 flex items-center gap-4"><div class="grid h-20 w-20 place-items-center overflow-hidden rounded-2xl bg-blue-100 text-2xl font-bold text-blue-700"><?php if(!empty($u['foto'])):?><img src="<?=e(app_url('uploads/associados/'.$u['foto']))?>" class="h-full w-full object-cover"><?php else:?><?=e(strtoupper(substr($u['nome'],0,1)))?><?php endif;?></div><label class="text-sm font-semibold">Foto do associado<input name="foto" type="file" accept="image/jpeg,image/png,image/webp" class="mt-2 block text-sm font-normal"></label></div><div class="grid gap-5 md:grid-cols-2"><label class="text-sm font-semibold">Nome<input name="nome" required value="<?=e($u['nome'])?>" class="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 font-normal"></label><label class="text-sm font-semibold">E-mail<input name="email" type="email" required value="<?=e($u['email'])?>" class="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 font-normal"></label><label class="text-sm font-semibold">CPF<input name="cpf" required value="<?=e($u['cpf'])?>" class="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 font-normal"></label><label class="text-sm font-semibold">Matrícula<input name="matricula" required value="<?=e($u['matricula'])?>" class="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 font-normal"></label><label class="text-sm font-semibold">Status<select name="status_financeiro" class="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 font-normal"><?php foreach(['EM_DIA'=>'Em dia','DEVEDOR'=>'Devedor','DESFILIADO'=>'Desfiliado'] as $v=>$l):?><option value="<?=$v?>" <?=$u['status_financeiro']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label></div><div class="mt-7 flex justify-end gap-3"><a href="<?=e(app_url('admin/perfil.php?id='.$id))?>" class="rounded-lg border px-5 py-3 text-sm font-semibold">Cancelar</a><button class="rounded-lg bg-blue-600 px-5 py-3 text-sm font-bold text-white">Guardar alterações</button></div></form><?php admin_end();